<?php
declare(strict_types=1);
/* Personal-data logger migration. It is dry-run unless --apply is explicit. */
require_once __DIR__ . '/../classes/dbconnection.class.php';
$database = ''; $backup = ''; $apply = in_array('--apply', $argv, true);
$down = in_array('--apply-down', $argv, true); $confirmDrop = in_array('--confirm-drop', $argv, true);
foreach ($argv as $arg) {
    if (strpos($arg, '--database=') === 0) $database = substr($arg, 11);
    if (strpos($arg, '--backup=') === 0) $backup = substr($arg, 9);
}
if ((!in_array($database, ['ccc_database', 'ccc_database_test'], true) && !preg_match('/^ccc_database_experiment_verify_[a-z0-9_]+$/', $database)) || ($apply && $down) || ($down && !$confirmDrop)) {
    fwrite(STDERR, "Specify an approved production, test, or ccc_database_experiment_verify_* database and one of --apply or --apply-down --confirm-drop.\n"); exit(2);
}
if ($apply && (!$backup || !is_file($backup) || filesize($backup) < 1024 || strpos(basename($backup), $database) === false)) {
    fwrite(STDERR, "Apply requires a verified, database-named --backup=<dump.sql> (>=1 KiB).\n"); exit(2);
}
$db = (new dbconnection())->connect($database); if (!$db) exit(2); $db->set_charset('utf8mb4');
if ($down) {
    $counts = [];
    foreach (['face_experiment_log', 'face_model_template', 'face_experiment_purge_ledger'] as $table) {
        $present = $db->query("SHOW TABLES LIKE '{$table}'");
        $counts[$table] = $present && $present->num_rows ? (int)$db->query("SELECT COUNT(*) n FROM `{$table}`")->fetch_assoc()['n'] : 0;
    }
    echo 'DOWN row counts ' . json_encode($counts) . "\n";
    foreach (["DROP VIEW IF EXISTS face_experiment_baseline_by_model", "DROP VIEW IF EXISTS face_experiment_status_by_model", "DROP VIEW IF EXISTS face_experiment_status", "DROP PROCEDURE IF EXISTS face_experiment_log_insert", "DROP EVENT IF EXISTS face_experiment_daily_purge", "DROP TABLE IF EXISTS face_experiment_purge_ledger", "DROP TABLE IF EXISTS face_model_template", "DROP TABLE IF EXISTS face_experiment_log"] as $sql) {
        if (!$db->query($sql)) throw new RuntimeException($db->error);
    }
    echo "DOWN applied; only experiment tables, view, procedure, and purge event were dropped.\n"; exit(0);
}
$ddl = [
"CREATE TABLE IF NOT EXISTS face_experiment_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,experiment_id CHAR(64) NOT NULL,source ENUM('PRIMARY','SHADOW') NOT NULL,opaque_id_version SMALLINT UNSIGNED NOT NULL,scan_opaque_id CHAR(66) NULL,session_opaque_id CHAR(66) NULL,branch_opaque_id CHAR(66) NULL,device_opaque_id CHAR(66) NULL,roster_size SMALLINT UNSIGNED NOT NULL,experiment_config_version VARCHAR(100) NOT NULL,model_name VARCHAR(100) NOT NULL,model_version VARCHAR(100) NOT NULL,runtime VARCHAR(100) NOT NULL,precision_mode VARCHAR(32) NOT NULL,artifact_checksum CHAR(64) NULL,preprocessing_version VARCHAR(100) NOT NULL,policy_version VARCHAR(100) NOT NULL,decision ENUM('ACCEPT','REVIEW','REJECT','ERROR') NOT NULL,outcome_code VARCHAR(64) NOT NULL,top1_score DECIMAL(10,7) NULL,top2_score DECIMAL(10,7) NULL,margin_score DECIMAL(10,7) NULL,consensus_count TINYINT UNSIGNED NOT NULL DEFAULT 0,template_support TINYINT UNSIGNED NOT NULL DEFAULT 0,label_source ENUM('NONE','TEACHER_CONFIRMED','CALIBRATION') NOT NULL DEFAULT 'NONE',pair_type ENUM('UNKNOWN','GENUINE','SIBLING','IMPOSTOR') NOT NULL DEFAULT 'UNKNOWN',edge_gate_status VARCHAR(64) NOT NULL DEFAULT 'NOT_REPORTED',planar_spoof_flag TINYINT(1) NOT NULL DEFAULT 0,ground_truth_member_id INT NULL,stage_latency_json JSON NOT NULL,peak_ram_mb DECIMAL(10,2) NULL,frame_scores_json JSON NOT NULL,expires_at DATETIME NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_face_experiment_id (experiment_id),KEY idx_face_experiment_expiry (expires_at),KEY idx_face_experiment_source_model (source,model_name,model_version),KEY idx_face_experiment_edge_gate (planar_spoof_flag,edge_gate_status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS face_model_template (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,member_id INT NOT NULL,model_name VARCHAR(100) NOT NULL,model_version VARCHAR(100) NOT NULL,template_version SMALLINT UNSIGNED NOT NULL,encryption_key_id VARCHAR(100) NOT NULL,encrypted_template MEDIUMTEXT NOT NULL,preprocessing_version VARCHAR(100) NOT NULL,status ENUM('ACTIVE','REVOKED','SUPERSEDED') NOT NULL DEFAULT 'ACTIVE',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,revoked_at DATETIME NULL,UNIQUE KEY uq_face_model_template_version(member_id,model_name,model_version,template_version),KEY idx_face_model_template_active(model_name,model_version,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS face_experiment_purge_ledger (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,export_sha256 CHAR(64) NOT NULL,exported_rows INT UNSIGNED NOT NULL,deleted_rows INT UNSIGNED NOT NULL,export_path VARCHAR(255) NOT NULL,exported_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,retain_until DATE NOT NULL,UNIQUE KEY uq_face_experiment_export_hash(export_sha256)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"ALTER TABLE face_experiment_log ADD COLUMN IF NOT EXISTS edge_gate_status VARCHAR(64) NOT NULL DEFAULT 'NOT_REPORTED', ADD COLUMN IF NOT EXISTS planar_spoof_flag TINYINT(1) NOT NULL DEFAULT 0",
"ALTER TABLE face_experiment_log ADD INDEX IF NOT EXISTS idx_face_experiment_edge_gate (planar_spoof_flag,edge_gate_status)",
"CREATE OR REPLACE VIEW face_experiment_status AS SELECT COUNT(*) total_rows,SUM(source='PRIMARY') primary_rows,SUM(source='SHADOW') shadow_rows,SUM(planar_spoof_flag=1) quarantined_planar_rows,SUM(expires_at<NOW()) expired_rows,MAX(created_at) latest_row_at,(SELECT COALESCE(SUM(data_length+index_length),0) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='face_experiment_log') table_bytes,(SELECT MAX(exported_at) FROM face_experiment_purge_ledger) latest_export_at,(SELECT export_sha256 FROM face_experiment_purge_ledger ORDER BY id DESC LIMIT 1) latest_export_sha256 FROM face_experiment_log",
"CREATE OR REPLACE VIEW face_experiment_status_by_model AS SELECT source,model_name,model_version,planar_spoof_flag,edge_gate_status,COUNT(*) row_count FROM face_experiment_log GROUP BY source,model_name,model_version,planar_spoof_flag,edge_gate_status",
"CREATE OR REPLACE VIEW face_experiment_baseline_by_model AS SELECT source,model_name,model_version,COUNT(*) row_count FROM face_experiment_log WHERE planar_spoof_flag = 0 GROUP BY source,model_name,model_version",
"DROP PROCEDURE IF EXISTS face_experiment_log_insert",
"CREATE PROCEDURE face_experiment_log_insert(IN p_record JSON) BEGIN IF p_record IS NULL OR JSON_EXTRACT(p_record,'$.ground_truth_member_id') IS NOT NULL OR JSON_LENGTH(JSON_EXTRACT(p_record,'$.frame_scores_json.s')) <> 3 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='invalid experiment log record'; END IF; INSERT INTO face_experiment_log(experiment_id,source,opaque_id_version,scan_opaque_id,session_opaque_id,branch_opaque_id,device_opaque_id,roster_size,experiment_config_version,model_name,model_version,runtime,precision_mode,artifact_checksum,preprocessing_version,policy_version,decision,outcome_code,top1_score,top2_score,margin_score,consensus_count,template_support,label_source,pair_type,edge_gate_status,planar_spoof_flag,stage_latency_json,peak_ram_mb,frame_scores_json,expires_at) VALUES(JSON_UNQUOTE(JSON_EXTRACT(p_record,'$.experiment_id')),JSON_UNQUOTE(JSON_EXTRACT(p_record,'$.source')),JSON_EXTRACT(p_record,'$.opaque_id_version'),JSON_UNQUOTE(JSON_EXTRACT(p_record,'$.scan_opaque_id')),JSON_UNQUOTE(JSON_EXTRACT(p_record,'$.session_opaque_id')),JSON_UNQUOTE(JSON_EXTRACT(p_record,'$.branch_opaque_id')),JSON_UNQUOTE(JSON_EXTRACT(p_record,'$.device_opaque_id')),JSON_EXTRACT(p_record,'$.roster_size'),JSON_UNQUOTE(JSON_EXTRACT(p_record,'$.experiment_config_version')),JSON_UNQUOTE(JSON_EXTRACT(p_record,'$.model_name')),JSON_UNQUOTE(JSON_EXTRACT(p_record,'$.model_version')),JSON_UNQUOTE(JSON_EXTRACT(p_record,'$.runtime')),JSON_UNQUOTE(JSON_EXTRACT(p_record,'$.precision_mode')),JSON_UNQUOTE(JSON_EXTRACT(p_record,'$.artifact_checksum')),JSON_UNQUOTE(JSON_EXTRACT(p_record,'$.preprocessing_version')),JSON_UNQUOTE(JSON_EXTRACT(p_record,'$.policy_version')),JSON_UNQUOTE(JSON_EXTRACT(p_record,'$.decision')),JSON_UNQUOTE(JSON_EXTRACT(p_record,'$.outcome_code')),JSON_EXTRACT(p_record,'$.top1_score'),JSON_EXTRACT(p_record,'$.top2_score'),JSON_EXTRACT(p_record,'$.margin_score'),COALESCE(JSON_EXTRACT(p_record,'$.consensus_count'),0),COALESCE(JSON_EXTRACT(p_record,'$.template_support'),0),COALESCE(JSON_UNQUOTE(JSON_EXTRACT(p_record,'$.label_source')),'NONE'),COALESCE(JSON_UNQUOTE(JSON_EXTRACT(p_record,'$.pair_type')),'UNKNOWN'),COALESCE(JSON_UNQUOTE(JSON_EXTRACT(p_record,'$.edge_gate_status')),'NOT_REPORTED'),COALESCE(JSON_EXTRACT(p_record,'$.planar_spoof_flag'),0),COALESCE(JSON_EXTRACT(p_record,'$.stage_latency_json'),JSON_OBJECT()),JSON_EXTRACT(p_record,'$.peak_ram_mb'),JSON_EXTRACT(p_record,'$.frame_scores_json'),FROM_UNIXTIME(JSON_EXTRACT(p_record,'$.expires_at'))); END"
];
foreach ($ddl as $sql) { echo ($apply ? 'APPLY ' : 'PLAN ') . substr($sql, 0, 120) . "…\n"; if ($apply && !$db->query($sql)) throw new RuntimeException($db->error); }
if ($apply) echo 'BACKUP_SHA256 ' . hash_file('sha256', $backup) . "\nAPPLIED. Grant the writer only EXECUTE on face_experiment_log_insert; never raw-table access.\n";
$db->close();
